    const parse = (v) => {
        const [main, pre] = v.split('-');
        const parts = main.split('.');
        return {
            major: parseInt(parts[0]),
            minor: parseInt(parts[1]),
            patch: parseInt(parts[2]),
            preRelease: pre ? pre.split('.') : [],
        };
    };

    const aP = parse(a), bP = parse(b);

    if (aP.major !== bP.major) return aP.major < bP.major ? -1 : 1;
    if (aP.minor !== bP.minor) return aP.minor < bP.minor ? -1 : 1;
    if (aP.patch !== bP.patch) return aP.patch < bP.patch ? -1 : 1;

    const aPp = aP.preRelease, bPp = bP.preRelease;

    if (aPp.length === 0 && bPp.length === 0) return 0;
    if (aPp.length === 0) return 1;
    if (bPp.length === 0) return -1;

    for (let i = 0; i < Math.min(aPp.length, bPp.length); i++) {
