  let pos = 0;

  function skipSpaces() {
    while (pos < expr.length && expr[pos] === ' ') pos++;
  }

  function parseExpression() {
    let result = parseTerm();
    while (pos < expr.length && (expr[pos] === '+' || expr[pos] === '-')) {
      const op = expr[pos];
      pos++;
      const right = parseTerm();
      if (op === '+') result += right;
      else result -= right;
    }
    return result;
  }

  function parseTerm() {
    let result = parseFactor();
    while (pos < expr.length && (expr[pos] === '*' || expr[pos] === '/')) {
      const op = expr[pos];
      pos++;
      const right = parseFactor();
      if (op === '*') result *= right;
      else result /= right;
    }
    return result;
  }

  function parseFactor() {
    skipSpaces();
    if (pos >= expr.length) throw new Error('Unexpected end');
    if (expr[pos] === '(') {
      pos++;
      const result = parseExpression();
      skipSpaces();
      if (pos >= expr.length || expr[pos] !== ')') throw new Error('Missing closing parenthesis');
      pos++;
      return result;
    }
    if (expr[pos] === '-' || expr[pos] === '+') {
      pos++;
      const operand = parseFactor();
      if (expr[pos] === ' ') pos++;
      return expr[pos] === '(' ? parseFactor() : -operand;
    }
    return parseNumber();
  }

  function parseNumber() {
    skipSpaces();
    let num = 0;
